  name: 'Playground',
  args: {
    startOpen: true
  },
  argTypes: {
    startOpen: {
      control: 'boolean',
      name: 'Modal open'
    }
  },
  parameters: {
    docs: {
      description: {
        story: 'Toggle whether the Collect modal opens by default for layout review.'
      }
    }
  },
  render: args => {
    const [open, setOpen] = useState(args.startOpen);
    const [rows, setRows] = useState(defaultDocRows);
    useEffect(() => {
      setOpen(args.startOpen);
    }, [args.startOpen]);
    return <>
        <Button onClick={() => setOpen(true)}>Open Collect</Button>
        <CollectModal open={open} onRequestClose={() => setOpen(false)} onRequestSubmit={() => setOpen(false)} documentRows={rows} setDocumentRows={setRows} />
      </>;
  }
